#include <iostream>
#include <stdexcept>

class ResourceTracker {
    std::string name;
public:
    explicit ResourceTracker(std::string n) : name(std::move(n)) {
        std::cout << "Constructed: " << name << "\n";
    }
    ~ResourceTracker() {
        std::cout << "Destroyed: " << name << "\n";
    }
};

void function3() {
    ResourceTracker res3("LocalInFunc3");
    std::cout << "function3 throwing runtime_error\n";
    throw std::runtime_error("Critical failure in function3");
}

void function2() {
    ResourceTracker res2("LocalInFunc2");
    function3();
}

void function1() {
    try {
        function2();
    } catch (const std::exception& e) {
        std::cout << "function1 caught: " << e.what() << "; rethrowing\n";
        throw; // rethrow to main
    }
}

int main() {
    try {
        std::cout << "main calling function1\n";
        function1();
    } catch (const std::runtime_error& err) {
        std::cout << "main handled: " << err.what() << "\n";
    }
    std::cout << "Execution resumed safely in main\n";
    return 0;
}

#include <iostream>
#include <string>
#include <stdexcept>

class Member {
    std::string name;
public:
    explicit Member(std::string n) : name(std::move(n)) {
        std::cout << "Member constructed: " << name << "\n";
    }
    ~Member() noexcept {
        std::cout << "Member destroyed: " << name << "\n";
    }
};

class Composite {
    Member m1;
    Member m2;
public:
    Composite(int value) : m1("Member 1"), m2("Member 2") {
        std::cout << "Composite constructor running with value = " << value << "\n";
        if (value < 0) {
            throw std::invalid_argument("Negative value passed to Composite");
        }
    }
    ~Composite() noexcept {
        std::cout << "Composite destroyed\n";
    }
};

int main() {
    try {
        std::cout << "Attempting to construct Composite(-5)...\n";
        Composite comp(-5);
        std::cout << "This line should not print\n";
    } catch (const std::invalid_argument& ex) {
        std::cout << "Caught in main: " << ex.what() << "\n";
    }
    std::cout << "Program finished successfully\n";
    return 0;
}
